            {
              "text": "Ben Seri is listed as \"Co-Founder & CTO\" and his career history shows prior role as VP of Research at Armis.",
              "claimIds": [
                "zaf-063",
                "zaf-069"
              ]
            },
            {
              "text": "What it means for us: as a founder/CTO and technical evaluator he will prioritize integrations and technical fit during evaluations.",
              "claimIds": [
                "zaf-064",
                "zaf-063"
              ]
            }
          ],
          "sendLine": "",
          "contactRefs": [
            {
              "name": "Ben Seri"
            }
          ],
          "priority": 2
